mapper.select:
SELECT tmc.TRADE_MARKET tradeMarket, tmc.TRADE_PLAT tradePlat, tmc.ASSET_CLASSIFY1 assetType, tmc.ASSET_CLASSIFY2 assetType1, tmc.ASSET_CLASSIFY3 assetType2, tmc.IS_GRADE isGrade, tmcd.GRADE_CONDITION gradeCondition, tmcd.GRADE_AMT gradeAmt, tmcd.MINI_PRICE minPrice, tmc.EFF_DATE effDate FROM TRD_MINPRICE_CONFIG tmc LEFT JOIN TRD_MINPRICE_CONFIG_DETAIL tmcd ON tmc.SEQ_NO = tmcd.CONFIG_SEQ_NO
tmc.TRADE_PLAT = #{tradePlat}
and tmc.TRADE_MARKET = #{tradeMarket}
and tmc.ASSET_CLASSIFY1 = #{assetType}
and tmc.ASSET_CLASSIFY2 = #{assetType1}
and tmc.ASSET_CLASSIFY3 = #{assetType2}
and tmc.SEQ_NO in ( SELECT SEQ_NO FROM (SELECT ROW_NUMBER()OVER (PARTITION BY TRADE_MARKET ,TRADE_PLAT, ASSET_CLASSIFY1 ,ASSET_CLASSIFY2 ,ASSET_CLASSIFY3 ORDER BY EFF_DATE DESC)tn,SEQ_NO FROM TRD_MINPRICE_CONFIG where EFF_DATE <= to_date(#{date,jdbcType=VARCHAR},'yyyy-MM-dd')) t WHERE t.tn = 1 )
order by tmcd.GRADE_AMT,tmcd.GRADE_CONDITION

SELECT TRADE_MARKET tradeMarket, TRADE_PLAT tradePlat, ASSET_CLASSIFY1 assetType, ASSET_CLASSIFY2 assetType1, ASSET_CLASSIFY3 assetType2, IS_GRADE isGrade, EFF_DATE effDate FROM TRD_MINPRICE_CONFIG
TRADE_PLAT = #{tradePlat}
and TRADE_MARKET = #{tradeMarket}
and ASSET_CLASSIFY1 = #{assetType}
and (ASSET_CLASSIFY2 = #{assetType1} or ASSET_CLASSIFY2 is null)
and (ASSET_CLASSIFY3 = #{assetType2} or ASSET_CLASSIFY3 is null)
and SEQ_NO in ( SELECT SEQ_NO FROM (SELECT ROW_NUMBER()OVER (PARTITION BY TRADE_MARKET ,TRADE_PLAT, ASSET_CLASSIFY1 ,ASSET_CLASSIFY2 ,ASSET_CLASSIFY3 ORDER BY EFF_DATE DESC)tn,SEQ_NO FROM TRD_MINPRICE_CONFIG tmc where EFF_DATE <= to_date(#{date,jdbcType=VARCHAR},'yyyy-MM-dd')) t WHERE t.tn = 1 )

SELECT T1.TRADE_MARKET tradeMarket, T1.TRADE_PLAT tradePlat, T1.ASSET_CLASSIFY1 assetType, T1.ASSET_CLASSIFY2 assetType1, T1.ASSET_CLASSIFY3 assetType2, T1.PS ps, T1.MARKET_TYPE marketType, T1.MIN_NUM minNum, T1.MIN_NUM_UNIT minNumUnit, T1.MIN_AMT minAmt, T1.MAX_NUM maxNum, T1.MAX_NUM_UNIT maxNumUnit, T1.MAX_AMT maxAmt, T1.MIN_STEP minStep, T1.MIN_STEP_UNIT minStepUnit, T1.MIN_NUM_MARKET minNumMarket, T1.MIN_NUM_MARKET_UNIT minNumMarketUnit, T1.MAX_NUM_MARKET maxNumMarket, T1.MAX_NUM_MARKET_UNIT maxNumMarketUnit, T1.EFF_DATE effDate FROM TRD_ATTRIBUTE_CONFIG T1
T1.TRADE_PLAT = #{tradePlat}
and T1.TRADE_MARKET = #{tradeMarket}
and T1.ASSET_CLASSIFY1 = #{assetType}
and (T1.ASSET_CLASSIFY2 = #{assetType1} or T1.ASSET_CLASSIFY2 is null)
and (T1.ASSET_CLASSIFY3 = #{assetType2} or T1.ASSET_CLASSIFY3 is null)
and (T1.PS = #{ps} or T1.PS is null)
and (T1.MARKET_TYPE = #{marketType} or T1.MARKET_TYPE is null)
and T1.EFF_DATE <= to_date(#{date,jdbcType=VARCHAR},'yyyy-MM-dd')
and CONFIG_NO in ( SELECT CONFIG_NO FROM (SELECT ROW_NUMBER()OVER (PARTITION BY TRADE_MARKET ,TRADE_PLAT, ASSET_CLASSIFY1 ,ASSET_CLASSIFY2 ,ASSET_CLASSIFY3,PS,MARKET_TYPE ORDER BY EFF_DATE DESC)tn,CONFIG_NO FROM TRD_ATTRIBUTE_CONFIG where EFF_DATE <= to_date(#{date,jdbcType=VARCHAR},'yyyy-MM-dd')) t WHERE t.tn = 1 )

select T1.FINPROD_ID finprodId, T2.FINPROD_TYPE2 assetType, T2.FINPROD_MARKET_ID finprodMarketId, T1.OTH_CODE othCode, T1.OTH_TYPE othCodeType, T1.OTH_NAME othName, T1.DECLARED_PRICE declaredPrice, T1.DECLARED_START_DATE declaredStartDate, T1.DECLARED_END_DATE declaredEndDate FROM FIN_PRODUCT_OTH_CODE T1 LEFT JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID = T2.FINPROD_ID
1=1
and T1.FINPROD_ID = #{finprodId}
and (T2.FINPROD_MARKET_ID = #{finprodMarketId} OR T1.OTH_CODE = #{finprodMarketId})
and T1.OTH_TYPE = #{othCodeType}
and (case when T1.OTH_TYPE != #{FINPROD_OTH_CODE_TYPE_02} and T1.Declared_Start_Date <= to_date(#{date},'yyyy-MM-dd') and T1.Declared_End_Date >= to_date(#{date},'yyyy-MM-dd') then 1 when T1.OTH_TYPE = #{FINPROD_OTH_CODE_TYPE_02} then 1 else 0 end) = 1

select TRADE_MARKET tradeMarket, TRADE_PLAT tradePlat, ASSET_CLASSIFY1 assetType, ASSET_CLASSIFY2 assetType1, ASSET_CLASSIFY3 assetType2, EARLY_OPEN_TIME earlyOpenTime, EARLY_CLOSE_TIME earlyCLoseTime, NOON_OPEN_TIME noonOpenTime, NOON_CLOSE_TIME noonCLoseTime, NIGHT_OPEN_TIME nightOpenTime, NIGHT_CLOSE_TIME nightCLoseTime, DECLARATION_TYPE declarationType, IS_LAST_TRADE_DATE isLastTradeDate from TRD_TIME_CONFIG
TRADE_PLAT = #{tradePlat}
and TRADE_MARKET = #{tradeMarket}
and DECLARATION_TYPE = #{declarationType}
and ASSET_CLASSIFY1 = #{assetType}
and (ASSET_CLASSIFY2 = #{assetType1} or ASSET_CLASSIFY2 is null)
and (ASSET_CLASSIFY3 = #{assetType2} or ASSET_CLASSIFY3 is null)
and IS_LAST_TRADE_DATE = #{isLastTradeDate}

select TRADE_MARKET tradeMarket, TRADE_PLAT tradePlat, ASSET_CLASSIFY1 assetType, ASSET_CLASSIFY2 assetType1, ASSET_CLASSIFY3 assetType2, EARLY_OPEN_TIME earlyOpenTime, EARLY_CLOSE_TIME earlyCLoseTime, NOON_OPEN_TIME noonOpenTime, NOON_CLOSE_TIME noonCLoseTime, NIGHT_OPEN_TIME nightOpenTime, NIGHT_CLOSE_TIME nightCLoseTime, DECLARATION_TYPE declarationType from TRD_TIME_CONFIG
TRADE_PLAT = #{tradePlat}
and TRADE_MARKET = #{tradeMarket}
and DECLARATION_TYPE = #{declarationType}
and ASSET_CLASSIFY1 = #{assetType}
and (ASSET_CLASSIFY2 = #{assetType1} or ASSET_CLASSIFY2 is null)
and (ASSET_CLASSIFY3 = #{assetType2} or ASSET_CLASSIFY3 is null)

SELECT T.COUNTER_ID "counterId", T.LINK_ID "linkId", T.COUNTER_TYPE "counterType", T.COUNTER_NAME "counterName" FROM MST_COUNTER_PARTY T
AND T.COUNTER_TYPE = #{counterType}
AND (T.COUNTER_ID like concat('%',concat(#{counterId,jdbcType=VARCHAR},'%')) OR T.COUNTER_NAME like concat('%',concat(#{counterId,jdbcType=VARCHAR},'%')))
AND T.COUNTER_NAME = #{counterIdName, jdbcType=VARCHAR}
AND (T.COUNTER_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) OR T.COUNTER_NAME like concat('%',concat(#{search,jdbcType=VARCHAR},'%')))

SELECT
    T.COUNTER_ID "counterId",
    T.COUNTER_SEAT_ID "counterSeatId",
    T.COUNTER_TRADER_ID "counterTraderId"
FROM MST_COUNTER_PARTY_INFO T


        AND T.COUNTER_ID = #{counterId}


        AND T.COUNTER_TRADER_ID = #{counterTraderId,jdbcType=VARCHAR}


        AND T.COUNTER_SEAT_ID = #{counterSeatId,jdbcType=VARCHAR}

select sbmci.BROKER_ID brokerId, mci.CUSTOMER_NAME brokerName, sbmci.ACCT_NO acctNo, sci.ACCT_NAME acctNoStr,
sbmci.FINPROD_ID finprodId,
sbmci.MORE_CONVRATE moreConvrate from STD_BOND_MORE_CONVRATE_INFO sbmci left join mst_customer_info mci on mci.CUSTOMER_ID = sbmci.BROKER_ID left join STL_CAPACCT_INFO sci on sbmci.ACCT_NO = sci.ACCT_NO
sbmci.BROKER_ID = #{brokerId,jdbcType=VARCHAR}
AND sbmci.ACCT_NO = #{acctNo,jdbcType=VARCHAR}
AND sbmci.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

select sbmci.BROKER_ID brokerId, mci.CUSTOMER_NAME brokerName, sbmci.ACCT_NO acctNo, sci.ACCT_NAME acctNoStr, sbmci.MORE_CONVRATE moreConvrate from STD_BOND_MORE_CONVRATE_INFO sbmci left join mst_customer_info mci on mci.CUSTOMER_ID = sbmci.BROKER_ID left join STL_CAPACCT_INFO sci on sbmci.ACCT_NO = sci.ACCT_NO
sbmci.BROKER_ID = #{all}
AND sbmci.ACCT_NO = #{all}

select TEMP.PORTFOLIO_ID portfolioCode, TEMP.SEC_ACCT_ID, TEMP.FINPROD_ID, TEMP.OTH_TYPE as othCodeType, TEMP.CDATE "date", TEMP.QUTO, TEMP.IPO_QUTO, TEMP.BOND_ID, TEMP.TRADE_MARKET from ( select PORTFOLIO_ID, SEC_ACCT_ID, FINPROD_ID, OTH_TYPE, CDATE, QUTO, IPO_QUTO, BOND_ID, TRADE_MARKET, ROW_NUMBER() OVER(PARTITION BY PORTFOLIO_ID,OTH_TYPE,SEC_ACCT_ID,FINPROD_ID ORDER BY CDATE desc )rn from FIN_PRODUCT_QUTO
1=1
and SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
and PORTFOLIO_ID = #{portfolioId,jdbcType=VARCHAR}
and FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and OTH_TYPE = #{othCodeType,jdbcType=VARCHAR}
and BOND_ID = #{stockHolderNo,jdbcType=VARCHAR}
) TEMP where TEMP.rn = 1

select mdi.DEALER_NO, mci.CUSTOMER_NAME dealerName, MDDI.DEALER_PARTY_NO, MDDI.DEALER_PARTY_TYPE, MDDI.DEALER_PARTY_NAME, MDDI.TRADER_NO , MDDI.TRADER_NAME , MDDI.IS_OUR from MST_DEALER_INFO mdi LEFT JOIN MST_DEALER_DETAIL_INFO MDDI on mdi.DEALER_NO = MDDI.DEALER_NO and MDDI.CUSTOMER_ID=mdi.CUSTOMER_ID left join MST_CUSTOMER_INFO mci on mci.CUSTOMER_ID = mdi.CUSTOMER_ID left join MST_SALE_DEPARTMENT MSD on MDDI.CUSTOMER_ID =MSD.BROKER_ID LEFT JOIN STL_CAPACCT_INFO SCI ON MSD.SALE_DEPID = SCI.OWN_DEPT left join STL_SEC_ACCT_INFO SSAI on SCI.ACCT_NO = SSAI.TRD_ACCT_ID
mdi.TRADE_MARKET = #{tradePlace}
and SCI.ACCT_NO = #{acctNo}
and MDDI.IS_OUR = #{isOur}
and mdi.DEALER_NO = #{dealerNo}
and mci.CUSTOMER_ABBR like concat(concat('%',#{dealerName}),'%')
and MDDI.TRADER_NO like concat(concat('%',#{traderNo}),'%')
and MDDI.TRADER_NAME like concat(concat('%',#{traderName}),'%')
and MDDI.DEALER_PARTY_NO like concat(concat('%',#{dealerPartyNo}),'%')
and MDDI.DEALER_PARTY_NAME like concat(concat('%',#{dealerPartyName}),'%')

select * from (
select x.test_status isSppiPass
from sppi_test x
where x.finprod_id=#{finprodId,jdbcType=VARCHAR}
union
select t.is_sppi_pass
from SPPI_IMPORT_DATA t
where t.bond_id=#{finprodId,jdbcType=VARCHAR}
) where rownum=1
